import React, { useCallback, useMemo, useState } from 'react';
import {
  Button,
  Input,
  dispatchAppToast,
  getActiveCompanyCode,
  getAuthUser,
  LinPageLayout,
  useCatalogTableBusy,
  type LinListToolbarActionDef,
} from '@linm-soft-org/linm-web-common-components';
import { useAppDispatch } from '../../../store/hooks';
import { analyticsService } from '../../../services/analytics/analyticsService';
import type { CashLedgerLine } from '../../../services/analytics/models';
import { formatDate, formatVnd } from '../../../utils/formatters';
import { exportExcel, monthStartEnd } from '../../../utils/exportExcel';
import { getApiErrorMessage } from '../../../utils/getApiErrorMessage';
import erp from '../../../styles/erpPage.module.css';
import reportStyles from '../../../styles/erpReportPage.module.css';
import styles from './SoQuyPage.module.css';

const TEST_ID = 'rpt-so-quy';
const PAGE_ID = 'baocao-so-quy';
const TITLE = 'Sổ quỹ';

type ColKey =
  | 'contactName'
  | 'customerCode'
  | 'customerName'
  | 'counterAccountName'
  | 'maVv'
  | 'maPhi'
  | 'maHd'
  | 'maSp'
  | 'parentVoucherCode'
  | 'documentType';

const P1_COLS: { key: ColKey; label: string }[] = [
  { key: 'contactName', label: 'Ông bà' },
  { key: 'customerCode', label: 'Mã khách' },
  { key: 'customerName', label: 'Tên khách' },
  { key: 'counterAccountName', label: 'Tên TK đối ứng' },
  { key: 'maVv', label: 'Vụ việc' },
  { key: 'maPhi', label: 'Phí' },
  { key: 'maHd', label: 'Hợp đồng' },
  { key: 'maSp', label: 'Sản phẩm' },
  { key: 'parentVoucherCode', label: 'Mã CT mẹ' },
  { key: 'documentType', label: 'Mã CT' },
];

function sessionCompany(): string {
  return (getActiveCompanyCode() ?? getAuthUser()?.companyCode ?? '').trim();
}

function mapRowTag(raw: CashLedgerLine['rowTag']): 'detail' | 'Opening' | 'PeriodTotal' | 'Closing' {
  if (raw === 'Opening' || raw === 1) return 'Opening';
  if (raw === 'PeriodTotal' || raw === 2) return 'PeriodTotal';
  if (raw === 'Closing' || raw === 3) return 'Closing';
  return 'detail';
}

function normalizeItems(items: CashLedgerLine[]): CashLedgerLine[] {
  return items.map(r => {
    const rowTag = mapRowTag(r.rowTag);
    return {
      ...r,
      rowTag,
      isBold: rowTag !== 'detail',
      debitAmount: Number(r.debitAmount ?? 0),
      creditAmount: Number(r.creditAmount ?? 0),
      runningBalance: Number(r.runningBalance ?? 0),
    };
  });
}

const SoQuyPage: React.FC = () => {
  const dispatch = useAppDispatch();
  const initial = monthStartEnd();

  const [accountCode, setAccountCode] = useState('111');
  const [fromDate, setFromDate] = useState(initial.fromDate);
  const [toDate, setToDate] = useState(initial.toDate);
  const [groupByCounter, setGroupByCounter] = useState(true);
  const [colsOpen, setColsOpen] = useState(false);
  const [showCols, setShowCols] = useState<Record<ColKey, boolean>>(() =>
    Object.fromEntries(P1_COLS.map(c => [c.key, false])) as Record<ColKey, boolean>,
  );

  const [items, setItems] = useState<CashLedgerLine[]>([]);
  const [appliedFrom, setAppliedFrom] = useState('');
  const [appliedTo, setAppliedTo] = useState('');
  const [appliedAccount, setAppliedAccount] = useState('111');
  const [appliedGroup, setAppliedGroup] = useState(true);
  const [hasViewed, setHasViewed] = useState(false);
  const [loading, setLoading] = useState(false);
  const [filterError, setFilterError] = useState('');
  const { showTableLoading } = useCatalogTableBusy(loading);

  const visibleP1 = P1_COLS.filter(c => showCols[c.key]);

  const summary = useMemo(() => {
    if (!hasViewed) return null;
    const period = items.find(r => mapRowTag(r.rowTag) === 'PeriodTotal');
    const closing = items.find(r => mapRowTag(r.rowTag) === 'Closing');
    return {
      periodDebit: period?.debitAmount ?? 0,
      periodCredit: period?.creditAmount ?? 0,
      closingBalance: closing?.runningBalance ?? period?.runningBalance ?? 0,
    };
  }, [hasViewed, items]);

  const detailCount = useMemo(
    () => items.filter(r => mapRowTag(r.rowTag) === 'detail').length,
    [items],
  );

  const handleView = useCallback(() => {
    setFilterError('');
    const company = sessionCompany();
    if (!company) {
      setFilterError('Không xác định đơn vị');
      dispatchAppToast(dispatch, { message: 'Không xác định đơn vị', type: 'error' });
      return;
    }
    if (!fromDate.trim() || !toDate.trim()) {
      setFilterError('Chọn khoảng ngày');
      dispatchAppToast(dispatch, { message: 'Chọn khoảng ngày', type: 'error' });
      return;
    }
    if (toDate < fromDate) {
      setFilterError('Đến ngày phải ≥ Từ ngày');
      dispatchAppToast(dispatch, { message: 'Đến ngày phải ≥ Từ ngày', type: 'error' });
      return;
    }

    const acct = accountCode.trim() || '111';
    if (!accountCode.trim()) setAccountCode('111');

    setLoading(true);
    analyticsService
      .getCashLedgerReport({
        fromDate: fromDate.trim(),
        toDate: toDate.trim(),
        accountCode: acct,
        groupByCounter,
        reportKind: 'CashBook',
        pageSize: 500,
        includeChartData: false,
      })
      .then(report => {
        setItems(normalizeItems(report.items ?? []));
        setAppliedFrom(fromDate.trim());
        setAppliedTo(toDate.trim());
        setAppliedAccount(acct);
        setAppliedGroup(groupByCounter);
        setHasViewed(true);
      })
      .catch(err => {
        dispatchAppToast(dispatch, {
          message: getApiErrorMessage(err, 'Không tải được sổ quỹ'),
          type: 'error',
        });
      })
      .finally(() => setLoading(false));
  }, [accountCode, dispatch, fromDate, groupByCounter, toDate]);

  const onEnterView = useCallback(
    (e: React.KeyboardEvent) => {
      if (e.key === 'Enter') {
        e.preventDefault();
        handleView();
      }
    },
    [handleView],
  );

  const handleExport = useCallback(() => {
    if (!hasViewed || loading) return;
    const acct = appliedAccount || '111';
    const fileName = `so-quy_${acct}_${appliedFrom}_${appliedTo}.xlsx`;
    void exportExcel(
      '/accounting/cash-ledger/export-excel',
      {
        fromDate: appliedFrom,
        toDate: appliedTo,
        accountCode: acct,
        groupByCounter: appliedGroup,
        reportKind: 'CashBook',
        pageSize: 0,
        includeChartData: false,
      },
      fileName,
    ).catch(() => {
      /* toast already in exportExcel */
    });
  }, [appliedAccount, appliedFrom, appliedGroup, appliedTo, hasViewed, loading]);

  const handlePrint = useCallback(() => {
    window.print();
  }, []);

  const handleRefresh = useCallback(() => {
    const next = monthStartEnd();
    setAccountCode('111');
    setFromDate(next.fromDate);
    setToDate(next.toDate);
    setGroupByCounter(true);
    setColsOpen(false);
    setFilterError('');
  }, []);

  const exportDisabled = !hasViewed || loading;

  const toolbarActions = useMemo<LinListToolbarActionDef[]>(
    () => [
      {
        id: 'refresh',
        action: 'refresh',
        placement: 'left',
        label: 'Làm mới',
        variant: 'secondary',
        testId: `${TEST_ID}-toolbar-refresh-btn`,
        disabled: loading,
        onClick: handleRefresh,
      },
      {
        id: 'exportExcel',
        action: 'exportExcel',
        placement: 'right',
        label: 'Xuất Excel',
        variant: 'secondary',
        testId: `${TEST_ID}-export-excel`,
        disabled: exportDisabled,
        onClick: handleExport,
      },
      {
        id: 'exportPrint',
        action: 'print',
        placement: 'right',
        label: 'In',
        variant: 'secondary',
        testId: `${TEST_ID}-export-print`,
        disabled: exportDisabled,
        onClick: handlePrint,
      },
    ],
    [exportDisabled, handleExport, handlePrint, handleRefresh, loading],
  );

  const subtitle =
    hasViewed && appliedFrom && appliedTo
      ? `Từ: ${formatDate(appliedFrom)} đến ngày ${formatDate(appliedTo)}`
      : undefined;

  const rowClassName = (tag: ReturnType<typeof mapRowTag>) => {
    if (tag === 'Opening') return styles.rowToneOpening;
    if (tag === 'PeriodTotal') return styles.rowTonePeriodTotal;
    if (tag === 'Closing') return styles.rowToneClosing;
    return undefined;
  };

  const listBody = showTableLoading ? null : (
    <div className={erp.tableWrapper}>
      {subtitle ? (
        <div data-testid={`${TEST_ID}-subtitle`} className={reportStyles.subtitle} style={{ marginBottom: '0.5rem' }}>
          {subtitle}
        </div>
      ) : null}
      <table className={reportStyles.table} data-testid={`${TEST_ID}-grid`}>
        <thead>
          <tr>
            <th>Ngày CT</th>
            <th>Số CT</th>
            <th>Diễn giải</th>
            <th>TK đối ứng</th>
            {visibleP1.map(c => (
              <th key={c.key}>{c.label}</th>
            ))}
            <th className={reportStyles.colRight}>PS nợ</th>
            <th className={reportStyles.colRight}>PS có</th>
            <th className={reportStyles.colRight}>Số dư</th>
          </tr>
        </thead>
        <tbody>
          {!hasViewed
            ? null
            : items.map((row, index) => {
                const tag = mapRowTag(row.rowTag);
                const balNeg = (row.runningBalance ?? 0) < 0;
                return (
                  <tr
                    key={`${tag}|${row.voucherCode ?? ''}|${row.entryDate ?? ''}|${row.counterAccountCode ?? ''}|${index}`}
                    className={rowClassName(tag)}
                    data-testid={`${TEST_ID}-row-${index}`}
                    data-row-tag={tag}
                  >
                    <td>{tag === 'detail' && row.entryDate ? formatDate(row.entryDate) : ''}</td>
                    <td>{tag === 'detail' ? (row.voucherCode ?? '') : ''}</td>
                    <td>{row.description ?? ''}</td>
                    <td>{tag === 'detail' ? (row.counterAccountCode ?? '') : ''}</td>
                    {visibleP1.map(c => (
                      <td key={c.key}>{tag === 'detail' ? p1Value(row, c.key) : ''}</td>
                    ))}
                    <td className={reportStyles.colRight}>
                      {tag === 'Closing' ? '' : formatVnd(row.debitAmount ?? 0)}
                    </td>
                    <td className={reportStyles.colRight}>
                      {tag === 'Closing' ? '' : formatVnd(row.creditAmount ?? 0)}
                    </td>
                    <td
                      className={[reportStyles.colRight, balNeg ? styles.cellBalanceNeg : undefined]
                        .filter(Boolean)
                        .join(' ')}
                    >
                      {tag === 'PeriodTotal' && closingUsesSeparateRow(items)
                        ? ''
                        : formatVnd(row.runningBalance ?? 0)}
                    </td>
                  </tr>
                );
              })}
        </tbody>
      </table>
      {hasViewed && detailCount === 0 ? (
        <div className={erp.empty} data-testid={`${TEST_ID}-empty`}>
          Không có phát sinh trong kỳ
        </div>
      ) : null}
    </div>
  );

  const footer =
    hasViewed && summary ? (
      <div className={styles.summaryBar} data-testid={`${TEST_ID}-summary`}>
        <span>PS nợ: {formatVnd(summary.periodDebit)}</span>
        <span>PS có: {formatVnd(summary.periodCredit)}</span>
        <span>Số dư cuối: {formatVnd(summary.closingBalance)}</span>
      </div>
    ) : undefined;

  return (
    <div
      className={erp.voucherListRoot}
      data-catalog-list-page
      data-report-list-page
      data-testid={`${TEST_ID}-list`}
    >
      <LinPageLayout
        kind="report"
        testIdPrefix={TEST_ID}
        pageId={PAGE_ID}
        pageClassName={`${erp.catalogListPage} ${erp.voucherListPage}`}
        header={{ title: TITLE, titleIconClass: 'fas fa-cash-register' }}
        listTitle={TITLE}
        filterMaxWidthPx={1200}
        showTableLoading={showTableLoading}
        skeletonRows={8}
        toolbarProps={{
          testIdPrefix: TEST_ID,
          profile: 'report',
          actions: toolbarActions,
        }}
        footer={footer}
        filters={(
          <>
            <div data-testid={`${TEST_ID}-field-accountCode`}>
              <Input
                label="Tài khoản quỹ"
                value={accountCode}
                onChange={e => setAccountCode(e.target.value)}
                onKeyDown={onEnterView}
                data-testid={`${TEST_ID}-field-accountCode`}
              />
            </div>
            <div data-testid={`${TEST_ID}-field-fromDate`}>
              <Input
                type="date"
                label="Từ ngày"
                value={fromDate}
                onChange={e => setFromDate(e.target.value)}
                onKeyDown={onEnterView}
                data-testid={`${TEST_ID}-field-fromDate`}
              />
            </div>
            <div data-testid={`${TEST_ID}-field-toDate`}>
              <Input
                type="date"
                label="Đến ngày"
                value={toDate}
                onChange={e => setToDate(e.target.value)}
                onKeyDown={onEnterView}
                data-testid={`${TEST_ID}-field-toDate`}
              />
            </div>
            <label className={styles.groupCheck} data-testid={`${TEST_ID}-field-groupByCounter`}>
              <input
                type="checkbox"
                checked={groupByCounter}
                onChange={e => setGroupByCounter(e.target.checked)}
                data-testid={`${TEST_ID}-field-groupByCounter`}
              />
              Nhóm theo chứng từ / TK đối ứng
            </label>
            <Button
              variant="primary"
              onClick={handleView}
              disabled={loading}
              data-testid={`${TEST_ID}-view-btn`}
            >
              Xem
            </Button>
            <Button
              variant="secondary"
              className={styles.colsToggle}
              onClick={() => setColsOpen(v => !v)}
              data-testid={`${TEST_ID}-cols-toggle`}
            >
              Cột thêm
            </Button>
            {colsOpen ? (
              <div className={styles.colsPanel} data-testid={`${TEST_ID}-cols-panel`}>
                {P1_COLS.map(c => (
                  <label key={c.key}>
                    <input
                      type="checkbox"
                      checked={showCols[c.key]}
                      onChange={e =>
                        setShowCols(prev => ({ ...prev, [c.key]: e.target.checked }))
                      }
                      data-testid={`${TEST_ID}-col-toggle-${c.key}`}
                    />{' '}
                    {c.label}
                  </label>
                ))}
              </div>
            ) : null}
            {filterError ? (
              <div className={styles.filterError} data-testid={`${TEST_ID}-filter-error`}>
                {filterError}
              </div>
            ) : null}
          </>
        )}
      >
        {listBody}
      </LinPageLayout>
    </div>
  );
};

function closingUsesSeparateRow(items: CashLedgerLine[]): boolean {
  return items.some(r => mapRowTag(r.rowTag) === 'Closing');
}

function p1Value(row: CashLedgerLine, key: ColKey): string {
  const v = row[key];
  return v == null ? '' : String(v);
}

export default SoQuyPage;
